NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Verbum Domini, quod factum est ad Michaeam Morasthiten, in diebus Ioathan, Achaz, et Ezechiae regum Iuda: quod vidit super Samariam, et Ierusalem.',
        2: 'Audite populi omnes, et attendat terra, et plenitudo eius: et sit Dominus Deus vobis in testem, Dominus de templo sancto suo.',
        3: 'Quia ecce Dominus egredietur de loco suo: et descendet, et calcabit super excelsa terrae.',
        4: 'Et consumentur montes subtus eum: et valles scindentur sicut cera a facie ignis, et sicut aquae, quae decurrunt in praeceps.',
        5: 'In scelere Iacob omne istud, et in peccatis domus Israel. quod scelus Iacob? nonne Samaria? et quae excelsa Iuda? nonne Ierusalem?',
        6: 'et ponam Samariam quasi acervum lapidum in agro cum plantatur vinea: et detraham in vallem lapides eius, et fundamenta eius revelabo.',
        7: 'Et omnia sculptilia eius concidentur, et omnes mercedes eius comburentur igne, et omnia idola eius ponam in perditionem: quia de mercedibus meretricis congregata sunt, et usque ad mercedem meretricis revertentur.',
        8: 'Super hoc plangam, et ululabo: vadam spoliatus, et nudus: faciam planctum velut draconum, et luctum quasi struthionum.',
        9: 'Quia desperata est plaga eius, quia venit usque ad Iuda, tetigit portam populi mei usque ad Ierusalem.',
        10: 'In Geth nolite annunciare, lacrymis ne ploretis, in domo Pulveris pulvere vos conspergite.',
        11: 'Et transite vobis habitatio Pulchra, confusa ignominia: non est egressa quae habitat in exitu: planctum Domus vicina accipiet ex vobis, quae stetit sibimet.',
        12: 'Quia infirmata est in bonum, quae habitat in amaritudinibus: quia descendit malum a Domino in portam Ierusalem.',
        13: 'Tumultus quadrigae stuporis habitanti Lachis: principium peccati est filiae Sion, quia in te inventa sunt scelera Israel.',
        14: 'Propterea dabit emissarios super hereditatem Geth: domos Mendacii in deceptionem regibus Israel.',
        15: 'Adhuc heredem adducam tibi quae habitas in Maresa: usque ad Odollam veniet gloria Israel.',
        16: 'Decalvare, et tondere super filios deliciarum tuarum: dilata calvitium tuum sicut aquila: quoniam captivi ducti sunt ex te.',
    },
    2: {
        1: 'Vae qui cogitatis inutile, et operamini malum in cubilibus vestris: in luce matutina faciunt illud, quoniam contra Deum est manus eorum.',
        2: 'Et concupierunt agros, et violenter tulerunt, et rapuerunt domos: et calumniabantur virum, et domum eius, virum, et hereditatem eius.',
        3: 'Idcirco haec dicit Dominus: Ecce ego cogito super familiam istam malum: unde non auferetis colla vestra, et non ambulabitis superbi, quoniam tempus pessimum est.',
        4: 'In die illa sumetur super vos parabola, et cantabitur canticum cum suavitate, dicentium: Depopulatione vastati sumus: pars populi mei commutata est: quomodo recedet a me, cum revertatur, qui regiones nostras dividat?',
        5: 'Propter hoc non erit tibi mittens funiculum sortis in coetu Domini.',
        6: 'O Israel Ne loquamini loquentes: Non stillabit super istos, non comprehendet confusio.',
        7: 'Dicit domus Iacob: Numquid abbreviatus est spiritus Domini, aut tales sunt cogitationes eius? Nonne verba mea bona sunt cum eo, qui recte graditur?',
        8: 'Et econtrario populus meus in adversarium consurrexit: desuper tunica pallium sustulistis: et eos, qui transibant simpliciter, convertistis in bellum.',
        9: 'Mulieres populi mei eiecistis de domo deliciarum suarum: a parvulis earum tulistis laudem meam in perpetuum.',
        10: 'Surgite, et ite, quia non habetis hic requiem: propter immunditiam eius corrumpetur putredine pessima.',
        11: 'Utinam non essem vir habens spiritum, et mendacium potius loquerer: stillabo tibi in vinum, et in ebrietatem: et erit super quem stillatur populus iste.',
        12: 'Congregatione congregabo Iacob totum te: in unum conducam reliquias Israel, pariter ponam illum quasi gregem in ovili, quasi pecus in medio caularum, tumultuabuntur a multitudine hominum.',
        13: 'Ascendet enim pandens iter ante eos: divident, et transibunt portam, et ingredientur per eam: et transibit rex eorum coram eis, et Dominus in capite eorum.',
    },
    3: {
        1: 'Et dixi: Audite princeps Iacob, et duces domus Israel: Numquid non vestrum est scire iudicium,',
        2: 'qui odio habetis bonum, et diligitis malum: qui violenter tollitis pelles eorum desuper eis, et carnem eorum desuper ossibus eorum?',
        3: 'Qui comederunt carnem populi mei, et pellem eorum desuper excoriaverunt: et ossa eorum confregerunt, et conciderunt sicut in lebete, et quasi carnem in medio ollae.',
        4: 'Tunc clamabunt ad Dominum, et non exaudiet eos: et abscondet faciem suam ab eis in tempore illo, sicut nequiter egerunt in adinventionibus suis.',
        5: 'Haec dicit Dominus super prophetas, qui seducunt populum meum: qui mordent dentibus suis, et praedicant pacem: et si quis non dederit in ore eorum quippiam, sanctificant super eum praelium.',
        6: 'Propterea nox vobis pro visione erit, et tenebrae vobis pro divinatione: et occumbet sol super prophetas, et obtenebrabitur super eos dies.',
        7: 'Et confundentur qui vident visiones, et confundentur divini: et operient omnes vultos suos, quia non est responsum Dei.',
        8: 'Verumtamen ego repletus sum fortitudine spiritus Domini, iudicio, et virtute: ut annunciem Iacob scelus suum, et Israel peccatum suum.',
        9: 'Audite hoc principes domus Iacob, et iudices domus Israel: qui abominamini iudicium, et omnia recta pervertitis.',
        10: 'Qui aedificatis Sion in sanguinibus, et Ierusalem in iniquitate.',
        11: 'Principes eius in muneribus iudicabant, et sacerdotes eius in mercede docebant, et prophetae eius in pecunia divinabant: et super Dominum requiescebant, dicentes: Numquid non Dominus in medio nostrum? non venient super nos mala.',
        12: 'Propter hoc, causa vestri, Sion quasi ager arabitur, et Ierusalem quasi acervus lapidum erit, et mons templi in excelsa silvarum.',
    },
    4: {
        1: 'Et erit: In novissimo dierum erit mons domus Domini praeparatus in vertice montium, et sublimis super colles: et fluent ad eum populi.',
        2: 'Et properabunt gentes multae, et dicent: Venite, ascendamus ad montem Domini, et ad domum Dei Iacob: et docebit nos de viis suis, et ibimus in semitis eius: quia de Sion egredietur lex, et verbum Domini de Ierusalem.',
        3: 'Et iudicabit inter populos multos, et corripiet gentes fortes usque in longinquum: et concident gladios suos in vomeres, et hastas suas in ligones: non sumet gens adversus gentem gladium: et non discent ultra belligerare.',
        4: 'Et sedebit vir subtus vitem suam, et subtus ficum suam, et non erit qui deterreat: quia os Domini exercituum locutum est.',
        5: 'Quia omnes populi ambulabunt unusquisque in nomine Dei sui: nos autem ambulabimus in nomine Domini Dei nostri in aeternum et ultra.',
        6: 'In die illa, dicit Dominus, congregabo claudicantem: et eam, quam eieceram, colligam: et quam afflixeram consolabor:',
        7: 'Et ponam claudicantem in reliquias: et eam, quae laboraverat, in gentem robustam: et regnabit Dominus super eos in monte Sion, ex hoc nunc et usque in aeternum.',
        8: 'Et tu turris gregis nebulosa filia Sion usque ad te veniet: et veniet potestas prima, regnum filiae Ierusalem.',
        9: 'Nunc quare moerore contraheris? numquid rex non est tibi, aut consiliarius tuus periit, quia comprehendit te dolor sicut parturientem?',
        10: 'Dole, et satage filia Sion quasi parturiens: quia nunc egredieris de civitate, et habitabis in regione, et venies usque ad Babylonem, ibi liberaberis: ibi redimet te Dominus de manu inimicorum tuorum.',
        11: 'Et nunc congregatae sunt super te gentes multae, quae dicunt: Lapidetur: et aspiciat in Sion oculus noster.',
        12: 'Ipsi autem non cognoverunt cogitationes Domini, et non intellexerunt consilium eius: quia congregavit eos quasi foenum areae.',
        13: 'Surge, et tritura filia Sion: quia cornu tuum ponam ferreum, et ungulas tuas ponam aereas: et comminues populos multos, et interficies Domino rapinas eorum, et fortitudinem eorum Domino universae terrae.',
    },
    5: {
        1: 'Nunc vastaberis filia latronis: obsidionem posuerunt super nos, in virga percutient maxillam iudicis Israel.',
        2: 'ET TU BETHLEHEM Ephrata parvulus es in millibus Iuda: ex te mihi egredietur qui sit dominator in Israel, et egressus eius ab initio, a diebus aeternitatis.',
        3: 'Propter hoc dabit eos usque ad tempus, in quo parturiens pariet: et reliquiae fratrum eius convertentur ad filios Israel.',
        4: 'Et stabit, et pascet in fortitudine Domini, in sublimitate nominis Domini Dei sui: et convertentur, quia nunc magnificabitur usque ad terminos terrae.',
        5: 'Et erit iste pax: cum venerit Assyrius in terram nostram, et quando calcaverit domibus nostris: et suscitabimus super eum septem pastores, et octo primates homines:',
        6: 'Et pascent terram Assur in gladio, et terram Nemrod in lanceis eius: et liberabit ab Assur cum venerit in terram nostram, et cum calcaverit in finibus nostris.',
        7: 'Et erunt reliquiae Iacob in medio populorum multorum quasi ros a Domino, et quasi stillae super herbam, quae non expectat virum, et non praestolatur filios hominum.',
        8: 'Et erunt reliquiae Iacob in Gentibus in medio populorum multorum, quasi leo in iumentis silvarum, et quasi catulus leonis in gregibus pecorum: qui cum transierit, et conculcaverit, et ceperit, non est qui eruat.',
        9: 'Et exaltabitur manus tua super hostes tuos, et omnes inimici tui interibunt.',
        10: 'Et erit in die illa, dicit Dominus: Auferam equos tuos de medio tui, et disperdam quadrigas tuas.',
        11: 'Et perdam civitates terrae tuae, et destruam omnes munitiones tuas, et auferam maleficia de manu tua, et divinationes non erunt in te.',
        12: 'Et perire faciam sculptilia tua, et statuas tuas de medio tui: et non adorabis ultra opera manuum tuarum.',
        13: 'Et evellam lucos tuos de medio tui: et conteram civitates tuas.',
        14: 'Et faciam in furore et in indignatione ultionem in omnibus gentibus, quae non audierunt.',
    },
    6: {
        1: 'Audite quae Dominus loquitur: Surge, contende iudicio adversum montes, et audiant colles vocem tuam.',
        2: 'Audiant montes iudicium Domini, et fortia fundamenta terrae: quia iudicium Domini cum populo suo, et cum Israel diiudicabitur.',
        3: 'Popule meus quid feci tibi, aut quid molestus fui tibi? responde mihi.',
        4: 'Quia eduxi te de Terra Aegypti, et de domo servientium liberavi te: et misi ante faciem tuam Moysen, et Aaron, et Mariam?',
        5: 'Popule meus memento quaeso quid cogitaverit contra te Balach rex Moab, et quid responderit ei Balaam filius Beor, de Setim usque ad Galgalam, ut cognosceres iustitias Domini.',
        6: 'Quid dignum offeram Domino? curvabo genu Deo excelso? numquid offeram ei holocaustomata, et vitulos anniculos?',
        7: 'Numquid placari potest Dominus in millibus arietum, aut in multis millibus hircorum pinguium? numquid dabo primogenitum meum pro scelere meo fructum ventris mei pro peccato animae meae?',
        8: 'Indicabo tibi o homo quid sit bonum, et quid Dominus requirat a te: Utique facere iudicium, et diligere misericordiam, et solicitum ambulare cum Deo tuo.',
        9: 'Vox Domini ad civitatem clamat, et salus erit timentibus nomen eius: Audite tribus, et quis approbabit illud?',
        10: 'Adhuc ignis in domo impii thesauri iniquitatis, et mensura minor irae plena.',
        11: 'Numquid iustificabo stateram impiam, et saccelli pondera dolosa?',
        12: 'In quibus divites eius repleti sunt iniquitate, et habitantes in ea loquebantur mendacium, et lingua eorum fraudulenta in ore eorum.',
        13: 'Et ego ergo coepi percutere te perditione super peccatis tuis.',
        14: 'Tu comedes, et non saturaberis: et humiliatio tua in medio tui: et apprehendes, et non salvabis: et quos salvaveris, in gladium dabo.',
        15: 'Tu seminabis, et non metes: tu calcabis olivam, et non ungeris oleo: et mustum, et non bibes vinum.',
        16: 'Et custodisti praecepta Amri, et omne opus domus Achab: et ambulasti in voluptatibus eorum, ut darem te in perditionem, et habitantes in ea in sibilum et opprobrium populi mei portabitis.',
    },
    7: {
        1: 'Vae mihi, quia factus sum sicut qui colligit in autumno racemos vindemiae: non est botrus ad comedendum, praecoquas ficus desideravit anima mea.',
        2: 'Periit sanctus de terra, et rectus in hominibus non est: omnes in sanguine insidiantur, vir fratrem suum ad mortem venatur.',
        3: 'Malum manuum suarum dicunt bonum: princeps postulat, et iudex in reddendo est: et magnus locutus est desiderium animae suae, et conturbaverunt eam.',
        4: 'Qui optimus in eis est, quasi paliurus: et qui rectus, quasi spina de sepe. Dies speculationis tuae, visitatio tua venit: nunc erit vastitas eorum.',
        5: 'Nolite credere amico: et nolite confidere in duce: ab ea, quae dormit in sinu tuo, custodi claustra oris tui.',
        6: 'Quia filius contumeliam facit patri, et filia consurgit adversus matrem suam, nurus adversus socrum suam: et inimici hominis domestici eius.',
        7: 'Ego autem ad Dominum aspiciam, expectabo Deum salvatorem meum: audiet me Deus meus.',
        8: 'Ne laeteris inimica mea super me, quia cecidi: consurgam, cum sedero in tenebris, Dominus lux mea est.',
        9: 'Iram Domini portabo, quoniam peccavi ei, donec causam meam iudicet, et faciat iudicium meum: educet me in lucem, videbo iustitiam eius.',
        10: 'Et aspiciet inimica mea, et operietur confusione, quae dicit ad me: Ubi est Dominus Deus tuus? Oculi mei videbunt in eam: nunc erit in conculcationem ut lutum platearum.',
        11: 'Dies, ut aedificentur maceriae tuae: in die illa longe fiet lex.',
        12: 'In die illa usque ad te veniet Assur, et usque ad civitates munitas: et a civitatibus munitis usque ad flumen, et ad mare de mari, et ad montem de monte.',
        13: 'Et terra erit in desolationem propter habitatores suos, et propter fructum cogitationum eorum.',
        14: 'Pasce populum tuum in virga tua, gregem hereditatis tuae habitantes solos in saltu, in medio Carmeli: pascentur Basan et Galaad iuxta dies antiquos.',
        15: 'Secundum dies egressionis tuae de Terra Aegypti ostendam ei mirabilia.',
        16: 'Videbunt gentes, et confundentur super omni fortitudine sua: ponent manum super os, aures eorum surdae erunt.',
        17: 'Lingent pulverem sicut serpentes, velut reptilia terrae turbabuntur de aedibus suis: Dominum Deum nostrum desiderabunt, et timebunt te.',
        18: 'Quis Deus similis tui, qui aufers iniquitatem, et transis peccatum reliquiarum hereditatis tuae? non immittet ultra furorem suum, quoniam volens misericordiam est.',
        19: 'Revertetur, et miserebitur nostri: deponet iniquitates nostras, et proiiciet in profundum maris omnia peccata nostra.',
        20: 'Dabis veritatem Iacob, misericordiam Abraham: quae iurasti patribus nostris a diebus antiquis.',
    },
}
